class KPadded : KSepaField() { var q1 = 0L; var q2 = 0L; var q3 = 0L; var q4 = 0L; var q5 = 0L; var q6 = 0L; var q7 = 0L; var q8 = 0L }

fun main() {
    printLayout(KAdjacent::class.java)
    printLayout(KPadded::class.java)
